API_PAUSE = timedelta(minutes=5)  # ошибка API (обрыв сети, 5xx): запуски на паузе, по образцу лимита сессии
API_AUTH_PAUSE = timedelta(minutes=30)  # вход истёк: повтор бессмыслен, пока CEO не войдёт заново
